#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_size;
uniform float amzp_angle;
uniform float amzp_alpha;
uniform float amzp_solidity;
uniform float amzp_fill;
uniform float amzp_fade;
uniform float amzp_fadeType;
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
uniform float amzp_gradType;
uniform float2 amzp_position;
uniform float amzp_scale;
uniform float amzp_angleg;
       float2x2 rot2m(float a){
 float s = sin(a);
 float c = cos(a);
 return float2x2(c, -s, s, c);
        }
        float projectAndClampDist(float2 a, float2 b) {
            return clamp(dot(a,b)/dot(b,b),0.0,1.0);
        }
        void amzRender() {
        float2 satriyaid;
        satriyaid = amzScreenNorm();
        satriyaid /= amzp_scale;
        satriyaid *= rot2m((0.0+amzp_angleg)*0.0174533);
        satriyaid += float2((0.0+amzp_position.x), (0.0+amzp_position.y))*float2(-1.,1.)/500.;
            float t;
            if( int(amzp_gradType) == 0 ) {
                t = satriyaid.x;
            } else if ( int(amzp_gradType) == 1 ) {
                t = length( satriyaid - 0.5 ) * 2.0;
            } else if ( int(amzp_gradType) == 2 ) {
                float2 xy = satriyaid - 0.5;
                float2 zw = float2(0,1.0);
                float a = atan(xy.x, xy.y);
                float b = atan(zw.x, zw.y);
                t = mod(((a-b)+6.28),6.28)/6.28;
            } else {
                t = satriyaid.x;
            }
            t = clamp(t,0.0,1.0);
            float4 color = mix(amzp_color1, amzp_color2, t);
            float2 texelSize = 1.0 / getTexSize((screen.zw/1.0));
            float rad = amzp_angle * 0.0174533;
            float2 velocity = float2(cos(rad)*amzp_size,-sin(rad)*amzp_size);
            if( screen.zw.y > screen.zw.x ) {
                velocity.y *= screen.zw.x / screen.zw.y;
            } else {
                velocity.x *= screen.zw.y / screen.zw.x;
            }
            float speed = length(velocity / texelSize);
            int nSamples = int(clamp(speed, 1.01, 500.01));
            float maxAlpha = 0.0;
            float accumAlpha = 0.0;
            int minDist = nSamples;
            float4 baseColor = amzTexture(0,amzScreenNorm().st);
            for(int i=1; i<nSamples; i++ ) {
                float2 offset = velocity * (float(i) / float(nSamples - 1));
                float2 sampleCoord = amzScreenNorm().st-offset;
                float insideTexture = step(0.0,sampleCoord.x) * step(sampleCoord.x,1.0) * step(0.0,sampleCoord.y) * step(sampleCoord.y,1.0);
                float sampAlpha = amzTexture(0, sampleCoord).a * insideTexture;
                maxAlpha = max(maxAlpha, sampAlpha);
                if( sampAlpha > 0.5 ) {
                    minDist = amzIntMin(minDist,i);
                }
                float adjAlpha = sampAlpha*amzp_solidity*0.25;
                accumAlpha = adjAlpha + accumAlpha*(1.0-adjAlpha);
            }
            float resultAlpha = mix(accumAlpha,maxAlpha,amzp_solidity);
            float dist = 0.0;
            if( int(amzp_fadeType)==0 ) {
                dist = float(minDist)/float(nSamples);
            } else if( int(amzp_fadeType)==1 ) {
                dist = projectAndClampDist(amzScreenNorm()-(amzLayerCenter()/screen.zw),velocity);
            } else if( int(amzp_fadeType)==2 ) {
                dist = abs((amzScreenNorm()-(amzLayerCenter()/screen.zw)).x) / abs(velocity.x);
            } else if( int(amzp_fadeType)==3 ) {
                dist = abs((amzScreenNorm()-(amzLayerCenter()/screen.zw)).y) / abs(velocity.y);
            }
            amzOutput = mix(color * amzp_alpha * (1.0-dist*amzp_fade) * resultAlpha, baseColor, baseColor.a * amzp_fill);
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
